package com.plantgrowth.forecasting.entity; import jakarta.persistence.*; @Entity @Table(name="growing_locations") public class GrowingLocation {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="location_name") private String locationName; private Double latitude; private Double longitude; @Column(name="location_description") private String locationDescription; public Long getId(){return id;}public String getLocationName(){return locationName;}public void setLocationName(String x){locationName=x;}}
